import io
from rich.console import Console

class ClosingFile(io.TextIOBase):
    def __init__(self):
        self.closed = False
        self.count = 0

    def write(self, s):
        self.count += 1
        if self.count > 5:
            self.closed = True
            raise BrokenPipeError("Broken pipe")
        return len(s)

    def flush(self):
        if self.closed:
            raise BrokenPipeError("Broken pipe")

file = ClosingFile()
console = Console(file=file)

try:
    for i in range(20):
        console.print(f"Line {i}")
        print(f"Printed {i}")
except BrokenPipeError:
    print("Caught BrokenPipeError!")
except Exception as e:
    print(f"Caught unexpected exception: {type(e).__name__}: {e}")

print("Done")

